
-- Initial complete Minglora gift catalogue, metadata fields and exact 50/50 earnings split.
BEGIN;
ALTER TABLE public.live_gift_catalog
  ADD COLUMN IF NOT EXISTS image_url text,
  ADD COLUMN IF NOT EXISTS sound_preset text NOT NULL DEFAULT 'gift-default-1',
  ADD COLUMN IF NOT EXISTS animation_duration_ms integer NOT NULL DEFAULT 1600,
  ADD COLUMN IF NOT EXISTS asset_version text NOT NULL DEFAULT '1';

ALTER TABLE public.live_gift_catalog DROP CONSTRAINT IF EXISTS live_gift_catalog_coin_price_check;
ALTER TABLE public.live_gift_catalog ADD CONSTRAINT live_gift_catalog_coin_price_check CHECK (coin_price >= 1);
ALTER TABLE public.live_gift_transactions DROP CONSTRAINT IF EXISTS live_gift_transactions_coin_amount_check;
ALTER TABLE public.live_gift_transactions ADD CONSTRAINT live_gift_transactions_coin_amount_check CHECK (coin_amount >= 1);

ALTER TABLE public.live_gift_transactions
  ALTER COLUMN creator_share_minor TYPE numeric(20,2) USING creator_share_minor::numeric,
  ALTER COLUMN platform_share_minor TYPE numeric(20,2) USING platform_share_minor::numeric;
ALTER TABLE public.creator_earnings_ledger
  ALTER COLUMN creator_share_minor TYPE numeric(20,2) USING creator_share_minor::numeric,
  ALTER COLUMN platform_share_minor TYPE numeric(20,2) USING platform_share_minor::numeric;

ALTER TABLE public.live_gift_transactions
  DROP CONSTRAINT IF EXISTS live_gift_transactions_check,
  DROP CONSTRAINT IF EXISTS live_gift_transactions_check1;
ALTER TABLE public.live_gift_transactions
  ADD CONSTRAINT live_gift_transactions_check CHECK (creator_share_minor + platform_share_minor = gross_minor),
  ADD CONSTRAINT live_gift_transactions_check1 CHECK (creator_share_minor = gross_minor::numeric / 2);
ALTER TABLE public.creator_earnings_ledger
  DROP CONSTRAINT IF EXISTS creator_earnings_ledger_check,
  DROP CONSTRAINT IF EXISTS creator_earnings_ledger_check1;
ALTER TABLE public.creator_earnings_ledger
  ADD CONSTRAINT creator_earnings_ledger_check CHECK (creator_share_minor + platform_share_minor = gross_minor),
  ADD CONSTRAINT creator_earnings_ledger_check1 CHECK (creator_share_minor = gross_minor::numeric / 2);

CREATE TEMP TABLE minglora_gift_import_067 (
  code text PRIMARY KEY,name text NOT NULL,category text NOT NULL,emoji text NOT NULL,
  animation_key text NOT NULL,coin_price integer NOT NULL CHECK (coin_price >= 1),
  active boolean NOT NULL,sort_order integer NOT NULL,model_url text,
  animation_preset text NOT NULL,image_url text NOT NULL,sound_preset text NOT NULL,
  animation_duration_ms integer NOT NULL,asset_version text NOT NULL
) ON COMMIT DROP;

